import matplotlib; matplotlib.use("Agg"); import matplotlib.pyplot as plt
WH = "/eos/home-r/rjiang/vbs_zh_codex_starter/p2/runs/multi_r1/wh"; CB = "/eos/home-r/rjiang/vbs_zh_codex_starter/p2/combination"; VW = f"{CB}/vh_ws"; PK = f"{CB}/paper"; ST = f"{WH}/work/stat"
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__))); from pin import COMMIT
os.makedirs(f"{PK}/tables", exist_ok=True); os.makedirs(f"{PK}/figures", exist_ok=True)
NUM = {}; MISS = []; SC = "p2/runs/multi_r1/wh/scripts/make_paper.py"
def rel(p): return p.replace("/eos/home-r/rjiang/vbs_zh_codex_starter/", "")
def J(path):
    return json.load(open(path)) if os.path.exists(path) else None
def get(o, ks):
    for k in ks:
        if o is None: return None
        o = o[k] if (isinstance(o, dict) and k in o) or (isinstance(o, list) and isinstance(k, int)) else None
    return o
def reg(key, path, *ks, value=None, note=None):
    """register value from json file `path` at key path ks (or a computed `value` with the source stated in note)"""
    v = value if value is not None else get(J(path), list(ks))
    if v is None: MISS.append(key); NUM[key] = dict(value=None, source=rel(path) + "::" + "/".join(map(str, ks)), script=SC); return None
    NUM[key] = dict(value=v, source=rel(path) + ("::" + "/".join(map(str, ks)) if ks else "") + (f" ({note})" if note else ""), script=SC); return v
def fmt(key, f="{:.3g}"):
    v = NUM[key]["value"]; return "--" if v is None else (f.format(v) if not isinstance(v, str) else v)
def tex(name, header, rows, caption):
    body = " \\\\\n".join(" & ".join(str(c) for c in r) for r in rows)
    s = "%% generated by make_paper.py (analysis commit %s); numbers from paper_numbers.json\n\\begin{table}[ht]\\centering\\small\n\\begin{tabular}{%s}\\hline\n%s \\\\\\hline\n%s \\\\\\hline\n\\end{tabular}\n\\caption{%s}\n\\end{table}\n" % (COMMIT, "l"+"r"*(len(header)-1), " & ".join(header), body, caption)
    open(f"{PK}/tables/{name}.tex", "w").write(s)
def fig(f, name): f.savefig(f"{PK}/figures/{name}.pdf"); f.savefig(f"{PK}/figures/{name}.png", dpi=130); plt.close(f)
LUM = (500, 1000, 3000); sv = f"{WH}/work/stat"
ZP = f"{VW}/zh_paper_inputs.json"; ZI = f"{VW}/zh_channel_inputs.json"; SELP = f"{WH}/work/sel/selection_v12.json"; CNT = f"{sv}/counting_v12.json"
