rows = []; SM = {r["sample"]: r for r in csv.DictReader(open("/eos/home-r/rjiang/vbs_zh_codex_starter/p2/production/wh/SAMPLES.csv"))}
SP = "/eos/home-r/rjiang/vbs_zh_codex_starter/p2/production/wh/SAMPLES.csv"
for s in ("S_EW_WHjj", "S_EW_WHjj_taunu", "B_QCD_Waajj_nomjj", "B_EW_Waajj_nomjj", "F_QCD_Wajjj_nomjj", "F_EW_Wajj_nomjj", "F_Wjjjj", "T_ttjj_1l", "T_tta_1l", "T_tWa_1l", "T_ttaa_1l", "V_WWa_WH", "V_WZa_WH", "V_ZZa_WH",
          "H_QCD_WH_mlm", "H_ggZH_wh", "H_ZH_tautau_wh", "H_ttH_1l", "H_ttH_dilep_wh", "H_tHq_lep", "H_tHW_1l", "H_VBFH_jj", "Q_aajjj", "F_QCD_llajj_loose_v12", "F_QCD_llajj_nomjj", "ZH_Zajj_eFake", "ZH_Zaajj_QCD_nomjj_lostlep", "ZH_Zaajj_EW_lostlep", "ZH_EW_ZHjj_lostlep", "ZH_QCD_ZHjj_lostlep"):
    if s not in SM: MISS.append("sample:" + s); continue
    r = SM[s]; sg = reg(f"wh.samples.{s}.sigma_pb", SP, s, value=float(r["sigma_pb_pre_decay"]), note="column sigma_pb_pre_decay"); k = reg(f"wh.samples.{s}.k", SP, s, value=float(r["k"]), note="column k"); n = reg(f"wh.samples.{s}.N", SP, s, value=int(float(r["N_generated_LHE"])), note="column N_generated_LHE")
