tex("T1_samples_WH", ["sample", "$\\sigma$ [pb]", "$k$ (BR factors)", "$N_{\\rm gen}$"], rows, "WH analysis samples (SAMPLES.csv; frozen ZH rows used as lost-lepton backgrounds and the v1.1/v1.2 rows included).")
