        rows.append((st["step"].replace("|", "$|$").replace(">", "$>$").replace("<", "$<$"), fmt(f"wh.cutflow.{i}.s", "{:.3f}"), fmt(f"wh.cutflow.{i}.b", "{:.3f}"), fmt(f"wh.cutflow.{i}.rawb", "{:d}")))
