            if lab == "WH": z = reg(f"res.{lab}.{d}.{L}.Z0", key, "full_syst_BB", "Z0"); m = reg(f"res.{lab}.{d}.{L}.mu95", key, "full_syst_BB", "mu95_exp", 1)
