tex("T6_nonprompt_scans", ["class", "norm. factor", "$Z_0$ (PL; ZH: Eq.1)", "$\\mu_{95}$"], rows, "Non-prompt normalisation scans at 500\\,fb$^{-1}$ (photon and lepton separately; D36 range $\\times0.3$--$\\times3$, larger factors are beyond D36).")
